const BF = {"game":"Battlefield 3","weapons":[{"name":"M16A3","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/f/f3/BF3_M16_ICON.png/revision/latest","kit":"Assault","fire":"Automatic, Semi-Automatic","rof":"800 RPM","magazine":"30 + 1 rounds","damage":"25 - 18.4","velocity":"650 m/s","ammo":"5.56x45mm NATO","unlock":"US: Default weapon","desc":"The M16A3 appears in most levels where the USMC is present. It is either found without attachments, or with an optic and underslung M320."},{"name":"AK-74M","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/c/ce/Ak74m.png/revision/latest","kit":"Assault","fire":"Full-automatic, Semi-automatic","rof":"650 RPM","magazine":"30 + 1 rounds","damage":"25 - 18.4","velocity":"600m/s","ammo":"5.45x39mm WP","unlock":"Default weapon (RU Assault)","desc":"The AK-74M is a weapon featured in Battlefield 3."},{"name":"M416","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/3/38/Battlelog-m416.png/revision/latest","kit":"Assault","fire":"Automatic, Semi-Automatic","rof":"750 RPM","magazine":"30 + 1 rounds","damage":"25 - 18.4","velocity":"600 m/s","ammo":"5.56x45mm NATO","unlock":"22,000 Assault score","desc":"The M416 is a weapon featured in Battlefield 3."},{"name":"AEK-971","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/d/dc/BF3_AEK971_ICON.png/revision/latest","kit":"Assault","fire":"Automatic, 3-Round Burst, Semi-Automatic","rof":"900 RPM","magazine":"30 + 1 rounds","damage":"25 - 18.4","velocity":"580 m/s","ammo":"5.45x39mm WP","unlock":"60,000 Assault score","desc":"The AEK-971 is a weapon featured in Battlefield 3. It has a high rate of fire with open sights and moderate recoil. The reload animation of the AEK-971 is nearly identical to the AN-94, with the player hitting the magazine release with the new magazine."},{"name":"F2000","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/2/22/F2000_Battlelog_Icon.png/revision/latest","kit":"Assault","fire":"Automatic, Semi-Automatic","rof":"850 RPM","magazine":"30 + 1 rounds","damage":"25 - 18.4","velocity":"600 m/s","ammo":"5.56x45mm NATO","unlock":"124,000 Assault score","desc":"The F2000 is a weapon featured in Battlefield 3"},{"name":"AN-94","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/7/77/BF3_AN-94_ICON.png/revision/latest","kit":"Assault","fire":"2-Round Burst, Automatic, Semi-Automatic","rof":"600 RPM (Automatic)","magazine":"30 + 1 rounds","damage":"25 - 18.4","velocity":"600 m/s","ammo":"5.45x39mm WP","unlock":"166,000 Assault score","desc":"The AN-94 is a weapon featured in Battlefield 3."},{"name":"G3A3","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/c/c9/G3a3.png/revision/latest","kit":"Assault","fire":"Automatic, Semi-Automatic","rof":"550 RPM","magazine":"20 + 1 rounds","damage":"34 - 22","velocity":"500 m/s","ammo":"7.62x51mm NATO","unlock":"","desc":"The G3A3 is a weapon featured in Battlefield 3."},{"name":"KH2002","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/4/45/BF3_KH2002_ICON.png/revision/latest","kit":"Assault","fire":"Three-rounds burst, Semi-automatic","rof":"800 RPM","magazine":"30 + 1 rounds","damage":"25 - 18.4","velocity":"650m/s","ammo":"5.56x45mm NATO","unlock":"17,000 Co-op score","desc":"The KH2002 makes its first appearance in Battlefield 3. It is an average-power, average-accuracy, three-round-burst assault rifle."},{"name":"FAMAS","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/4/40/BF3_FAMAS_ICON.png/revision/latest","kit":"Assault","fire":"Full-automatic, Three-rounds burst, Semi-automatic","rof":"1000 RPM","magazine":"25 + 1 rounds","damage":"25 - 18.4","velocity":"630m/s","ammo":"5.56x45mm NATO","unlock":"Best Friend Forever assignment","desc":"The FAMAS is a weapon featured in the Battlefield 3: Back to Karkand expansion. It was first seen on the \"Battlefield 3: Back to Karkand Gameplay Premiere Trailer\" with a Holographic Sight and a Laser Sight attached. It is the first unlockable assault weapon of the expansion pack and is obtained through the completion of the Best Friend Forever assignment."},{"name":"L85A2","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/e/e6/BF3_L85A2_ICON.png/revision/latest","kit":"Assault","fire":"Full-automatic, Three round burst, Semi-automatic","rof":"650 RPM","magazine":"30 + 1 rounds","damage":"25 - 17","velocity":"600m/s","ammo":"5.56x45mm NATO","unlock":"Professional Russian assignment","desc":"The L85A2 is an assault rifle featured in the Battlefield 3: Back to Karkand expansion pack. The weapon bears numerous similarities to the AK-74M in terms of handling, with the same rate of fire and similarly low recoil, but the L85A2 has a tendency to drift up and left rather than up and right, and is harsher in doing so than the AK-74M. Additionally, it has the highest spread recovery rate of all of the assault rifles. Like the F2000, it has the lowest spread of all full-auto assault rifles when aiming down the sights on the move, lower than M16A3 (1.0), though the L85A2\u0027s lower fire rate allows for more controllable automatic fire and conserve ammunition."},{"name":"AUG A3","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/1/12/AUG_A3.png/revision/latest","kit":"Assault","fire":"Full-automatic (default), Semi-automatic (Switching fire-mode)","rof":"700 RPM","magazine":"30 + 1 rounds","damage":"25 - 18.4","velocity":"670m/s","ammo":"5.56x45mm NATO","unlock":"Shepard assignment","desc":"The AUG A3 is an assault rifle featured in the Battlefield 3: Close Quarters expansion pack and is unlocked upon completion of the Shepard assignment. The entire weapon has a slightly less obtrusive profile when at the hip when compared to previous iterations of the weapon, and its sight picture follows suit, being virtually identical but seemingly thinner than the Bad Company variations."},{"name":"SCAR-L","group":"Assault Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/1/1d/SCAR-L.png/revision/latest","kit":"Assault","fire":"Full-automatic (default), Semi-automatic (Switching fire-mode)","rof":"620 RPM","magazine":"30 + 1 rounds","damage":"25 - 18.4","velocity":"580m/s","ammo":"5.56x45mm NATO","unlock":"Set Us Up The Bomb assignment","desc":"The SCAR-L is an assault rifle introduced in the Battlefield 3: Close Quarters expansion and is unlocked upon the completion of the Set Us Up The Bomb assignment. It was first seen in the killfeed during the Battlefield 3: Close Quarters Gameplay Premiere Trailer, although it was misspelled as SCARL-L. The gun itself is seen for the first time in a player\u0027s hands in the Donya Fortress Gameplay Trailer."},{"name":"M4A1","group":"Carbines","image":"https://static.wikia.nocookie.net/battlefield/images/a/a1/M4A1.png/revision/latest","kit":"Engineer","fire":"Full-automatic, Semi-automatic","rof":"800 RPM","magazine":"30 + 1 rounds","damage":"25 - 14.3","velocity":"580m/s","ammo":"5.56x45mm NATO","unlock":"• Default US Engineer weapon","desc":"The M4A1 is a weapon featured in Battlefield 3. It was first seen in the Fault Line Trailer."},{"name":"AKS-74u","group":"Carbines","image":"https://static.wikia.nocookie.net/battlefield/images/a/af/AKS-74U.png/revision/latest","kit":"Engineer","fire":"Automatic, Semi-Automatic","rof":"650 RPM","magazine":"30 + 1 rounds","damage":"25 - 14.3","velocity":"440 m/s","ammo":"","unlock":"Default (Russian Army)","desc":"The AKS-74u is a weapon featured in Battlefield 3."},{"name":"SCAR-H","group":"Carbines","image":"https://static.wikia.nocookie.net/battlefield/images/d/d5/SCAR-H_Battlelog_Icon.png/revision/latest","kit":"Engineer","fire":"Automatic, Semi-Automatic","rof":"600 RPM","magazine":"20 + 1 rounds","damage":"30 - 20","velocity":"420 m/s","ammo":"7.62x51mm NATO","unlock":"14,000 Engineer score","desc":"The SCAR-H is a weapon featured in Battlefield 3."},{"name":"A-91","group":"Carbines","image":"https://static.wikia.nocookie.net/battlefield/images/f/f1/A-91_Battlelog_Icon.png/revision/latest","kit":"Engineer","fire":"Automatic, Semi-Automatic","rof":"800 RPM","magazine":"30 + 1 rounds","damage":"25 - 14.3","velocity":"420 m/s","ammo":"5.56x45mm NATO","unlock":"58,000 Engineer score","desc":"The A-91 is a weapon featured in Battlefield 3 as the variant without a grenade launcher."},{"name":"G36C","group":"Carbines","image":"https://static.wikia.nocookie.net/battlefield/images/3/3c/BF3BL_G36C.png/revision/latest","kit":"Engineer","fire":"Automatic, 2-Round Burst, Semi-Automatic","rof":"750 RPM","magazine":"30 + 1 rounds","damage":"25 - 14.3","velocity":"500 m/s","ammo":"5.56x45mm NATO","unlock":"110,000 Engineer score","desc":"A cut down version of the German Army\u0027s full size G36 rifle, the C in G36C is stands for Commando or Compact. Equipped with a number of rails for accessories and a set of backup iron sights instead of the integrated optics and carry handle of the G36, the G36C is a Carbine with significant customization options. Its great ergonomics and short length make it excellent in short range encounters. The G36C also includes a 2 Round Burst mode."},{"name":"SG553","group":"Carbines","image":"https://static.wikia.nocookie.net/battlefield/images/e/e3/BF3BLSG553.png/revision/latest","kit":"Engineer","fire":"Full-automatic, Three-rounds burst, Semi-automatic","rof":"700 RPM","magazine":"30 + 1 rounds","damage":"25 - 14.3","velocity":"430m/s","ammo":"5.56x45mm NATO","unlock":"120,000 Co-op score","desc":"The SG553 is a Carbine featured in Battlefield 3."},{"name":"G53","group":"Carbines","image":"https://static.wikia.nocookie.net/battlefield/images/a/ab/BF3_G53_ICON.png/revision/latest","kit":"Engineer","fire":"Full-automatic, Three-rounds burst, Semi-automatic","rof":"750 RPM","magazine":"30 + 1 rounds","damage":"25 - 14.3","velocity":"450m/s","ammo":"5.56x45mm NATO","unlock":"Fixing It assignment","desc":"The G53 is a weapon introduced in the Battlefield 3: Back to Karkand expansion pack and is unlocked upon the completion of the Fixing It assignment."},{"name":"QBZ-95B","group":"Carbines","image":"https://static.wikia.nocookie.net/battlefield/images/b/b3/BF3_QBZ-95B_ICON.png/revision/latest","kit":"Engineer","fire":"Automatic, Three-round burst, Semi-automatic","rof":"650 RPM","magazine":"30 + 1 rounds","damage":"25 - 14.3","velocity":"490m/s","ammo":"5.8x42mm DAP-87","unlock":"It Goes Boom! assignment","desc":"The QBZ-95B is a weapon introduced in the Battlefield 3: Back to Karkand expansion and is unlocked upon the completion of the It Goes Boom! assignment."},{"name":"ACW-R","group":"Carbines","image":"https://static.wikia.nocookie.net/battlefield/images/0/0b/ACW-R.png/revision/latest","kit":"Engineer","fire":"Automatic, Semi-Automatic","rof":"850 RPM","magazine":"26 + 1 rounds","damage":"20 - 16.7","velocity":"500 m/s","ammo":"6.5x39mm Grendel","unlock":"","desc":"The ACW-R is a weapon introduced in the Battlefield 3: Close Quarters expansion and is unlocked upon the completion of the Done Fixing assignment. It was first seen in the Close Quarters Gameplay Premiere trailer."},{"name":"MTAR-21","group":"Carbines","image":"https://static.wikia.nocookie.net/battlefield/images/a/ae/MTAR-21.png/revision/latest","kit":"Engineer","fire":"Automatic, Semi-Automatic","rof":"900 RPM","magazine":"30 + 1 rounds","damage":"25 - 14.3","velocity":"570 m/s","ammo":"5.56x45mm NATO","unlock":"","desc":"The MTAR-21 is a weapon introduced in the Battlefield 3: Close Quarters expansion and is unlocked upon the completion of the My Own Terminator assignment. It was first seen in the killfeed of the Donya Fortress Gameplay trailer."},{"name":"M27 IAR","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/5/56/M27_IAR.png/revision/latest","kit":"Support","fire":"Fully-automatic, Semi-automatic","rof":"750 RPM","magazine":"45 + 1 rounds (without Extended Magazine)","damage":"25 - 18","velocity":"650m/s","ammo":"5.56x45mm NATO","unlock":"• Default US Support weapon","desc":"The M27 IAR is a weapon featured in Battlefield 3."},{"name":"RPK-74M","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/5/5f/RPK-74M.png/revision/latest","kit":"Support","fire":"Automatic, Semi-Automatic","rof":"700 RPM","magazine":"45 + 1 rounds","damage":"25 - 18.4","velocity":"600 m/s","ammo":"5.45x39mm WP","unlock":"Default (Russian Army)","desc":"The RPK-74M is a weapon featured in Battlefield 3."},{"name":"M249","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/3/3a/BF3_M249_ICON.png/revision/latest","kit":"Support","fire":"Full-automatic","rof":"800 RPM","magazine":"100 rounds","damage":"25 - 18.4","velocity":"620m/s","ammo":"5.56x45mm NATO","unlock":"11,000 Support score","desc":"The M249 is a weapon featured in Battlefield 3."},{"name":"PKP Pecheneg","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/d/d1/BF3_PKP_ICON.png/revision/latest","kit":"Support","fire":"Automatic","rof":"600 RPM","magazine":"100 rounds","damage":"34 - 22","velocity":"560 m/s","ammo":"7.62×54mmR","unlock":"60,000 Support score","desc":"The PKP Pecheneg is a weapon featured in Battlefield 3. It was first seen used in the Operation Métro gameplay trailer with a PK-A."},{"name":"M240B","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/f/f5/M240_BF3.png/revision/latest","kit":"Support","fire":"Automatic","rof":"750 RPM","magazine":"100 rounds","damage":"34 - 22","velocity":"610 m/s","ammo":"7.62×51mm NATO","unlock":"90,000 Support score","desc":"The M240B is a weapon featured in Battlefield 3."},{"name":"M60E4","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/5/5f/BF3_M60_ICON.png/revision/latest","kit":"Support","fire":"Automatic","rof":"580 RPM","magazine":"100 rounds","damage":"34 - 22","velocity":"560 m/s","ammo":"7.62x51mm NATO","unlock":"130,000 Support score","desc":"The M60E4 is a weapon featured in Battlefield 3."},{"name":"Type 88 LMG","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/2/26/BF3_Type_88_ICON.png/revision/latest","kit":"Support","fire":"Automatic","rof":"650 RPM","magazine":"100 rounds","damage":"25 - 18.4","velocity":"600 m/s","ammo":"5.8x42mm DAP-87","unlock":"","desc":"The Type 88 LMG is a Light Machine Gun featured in Battlefield 3. It can equip the same series of attachments as the other light machine guns, and like all light machine guns, it comes default with a Bipod."},{"name":"QBB-95","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/c/c6/BF3_QBB-95_ICON.png/revision/latest","kit":"Support","fire":"Full-automatic, Three-rounds burst, Semi-automatic","rof":"650 RPM","magazine":"75 + 1 rounds","damage":"25 - 18.4","velocity":"670m/s","ammo":"5.8x42mm DAP-87","unlock":"Let It Rain assignment","desc":"The QBB-95 is part of the Back to Karkand expansion along with 9 other weapons. It has a rate of fire of 650 rounds per minute and a drum magazine of 75+1 rounds. It has a fairly controllable amount of recoil due to its low fire rate in addition to having a burst fire mode. It can be unlocked by finishing the Let It Rain assignment. When initially unlocked, it came with an extended mag, a bipod, and a ballistic (12x) scope. The ballistic scope, extended mag and PKS-07 were removed in the March 2012 update, but the extended mag and the PKS-07 returned in the September 2012 patch."},{"name":"MG36","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/e/e4/BF3_MG36_ICON.png/revision/latest","kit":"Support","fire":"Full-automatic, Two-round burst, Semi-automatic","rof":"750 RPM","magazine":"50 + 1 rounds","damage":"25 - 18.4","velocity":"550m/s","ammo":"","unlock":"Keep Your Head Down assignment","desc":"The MG36 is a weapon introduced in the Back to Karkand expansion. The MG36 was first seen in the Back to Karkand Gameplay Premiere Trailer with the M145 MGO and a suppressor attached."},{"name":"L86A2","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/4/48/BF3_L86A2_ICON.png/revision/latest","kit":"Support","fire":"Full-automatic, Semi-automatic","rof":"750 RPM","magazine":"45 + 1 rounds","damage":"25 - 18.4","velocity":"640m/s","ammo":"5.56x45mm NATO","unlock":"No Shortage assignment","desc":"The L86A2 is a light machine gun featured in the Battlefield 3: Close Quarters expansion pack and Is unlocked upon the completion of the No Shortage assignment. The L86A2 is exclusive to the Support class. The L86A2 is a magazine-fed light machine gun, comparable to the M27 IAR and RPK-74M, possessing 45+1 round magazines by default, with all of the attachments available to those weapons, and has the same unlock progression (contrasted to the belt-fed light machine guns, where the unlocks are gained in a slightly different order). With Extended Mags, it has a 60+1 round mag."},{"name":"LSAT","group":"Light Machine Guns","image":"https://static.wikia.nocookie.net/battlefield/images/5/56/BF3_LSAT_ICON.png/revision/latest","kit":"Support","fire":"Automatic","rof":"650 RPM","magazine":"100 rounds","damage":"25 - 18.4","velocity":"620 m/s","ammo":"5.56x45mm LSAT","unlock":"","desc":"The LSAT is a weapon introduced in the Battlefield 3: Close Quarters expansion. It is unlocked upon completion of the Point Blank assignment."},{"name":"Mk11 Mod 0","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/3/39/BF3_MK11_ICON.png/revision/latest","kit":"Recon","fire":"Semi-automatic","rof":"260 RPM","magazine":"10 + 1 rounds","damage":"50 - 37.5","velocity":"550m/s","ammo":"7.62x51mm NATO","unlock":"• Default US Recon weapon","desc":"The Mk11 Mod 0 is a weapon featured in Battlefield 3."},{"name":"SVD","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/7/71/BF3_SVD_ICON.png/revision/latest","kit":"Recon","fire":"Semi-Automatic","rof":"260 RPM","magazine":"10 + 1 rounds","damage":"50 - 34","velocity":"530 m/s","ammo":"7.62×54mmR","unlock":"Default (Russian Army)","desc":"The SVD is a weapon featured in Battlefield 3."},{"name":"SV98","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/d/d4/BF3_SV-98_ICON.png/revision/latest","kit":"Recon","fire":"Bolt-action","rof":"48 RPM","magazine":"10 + 1 rounds","damage":"80 - 50","velocity":"520m/s","ammo":"7.62x54mm R","unlock":"13,000 Recon score","desc":""},{"name":"SKS","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/8/8f/BF3_SKS_ICON.png/revision/latest","kit":"Recon","fire":"Semi-automatic","rof":"333 RPM","magazine":"20 + 1 rounds","damage":"43 - 27","velocity":"440m/s","ammo":"7.62x39mm WP","unlock":"71,000 Recon score","desc":"The SKS is a weapon featured in Battlefield 3. It fulfills the role of a medium-range DMR. It takes 3–4 shots to the body to kill an enemy, or 1–2 shots to the head. With the Physical Warfare Pack, the player gets immediate access to it along with the Flash Suppressor which is exclusive to the pack. Otherwise, it is unlocked at 71,000 Recon score."},{"name":"M40A5","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/c/c6/BF3_M40A5_ICON.png/revision/latest","kit":"Recon","fire":"Bolt-action","rof":"54.5 RPM","magazine":"10 + 1 rounds","damage":"80 - 59","velocity":"490m/s","ammo":"7.62x51mm NATO","unlock":"104,000 Recon score","desc":"The M40A5 is a weapon featured in Battlefield 3 and is rather modernized compared to older variants."},{"name":"M98B","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/f/f3/BF3_M98B_ICON.png/revision/latest","kit":"Recon","fire":"Bolt-Action","rof":"46.15 RPM","magazine":"5 + 1 rounds","damage":"95 - 59","velocity":"650 m/s","ammo":".338 Magnum","unlock":"146,000 Recon score","desc":"A precision tactical rifle, the M98B uniquely was developed from the ground up as a Bolt-Action Sniper Rifle. Firing the .338 Magnum round from a detachable box magazine the M98B is capable of impressive accuracy and great stopping power even at extreme ranges. The M98B is currently being evaluated by US SOCOM in a modified form. By default the M98B is equipped with a Rifle Scope (8x)."},{"name":"M39 EMR","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/9/9f/BF3_M39EMR_ICON.png/revision/latest","kit":"Recon","fire":"Semi-Automatic","rof":"300 RPM","magazine":"10 + 1","damage":"50 - 37.5","velocity":"570 m/s","ammo":"7.62x51mm NATO","unlock":"58,000 Co-op score","desc":"The M39 EMR is a Sniper Rifle featured in Battlefield 3."},{"name":"QBU-88","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/e/eb/BF3_QBU-88_ICON.png/revision/latest","kit":"Recon","fire":"Semi-automatic","rof":"260 RPM","magazine":"10 + 1 rounds","damage":"50 - 37.5","velocity":"550m/s","ammo":"5.8x42mm DAP-88","unlock":"Specops assignment","desc":"The QBU-88 is a weapon introduced in the Battlefield 3: Back to Karkand expansion and is unlocked upon the completion of the Specops assignment. It holds 10+1 rounds per magazine. Notably, its iron sights are very occluded compared to other weapons."},{"name":"L96","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/e/eb/BF3_L96_ICON.png/revision/latest","kit":"Recon","fire":"Bolt-action","rof":"43.5 RPM","magazine":"10 + 1 rounds","damage":"80 - 59","velocity":"540m/s","ammo":"7.62x51mm NATO","unlock":"Creeping Death assignment","desc":""},{"name":"JNG-90","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/2/2d/JNG-90.png/revision/latest","kit":"Recon","fire":"Bolt-action","rof":"46.2 RPM","magazine":"10 + 1 Rounds","damage":"80 - 59","velocity":"560m/s","ammo":"7.62x51mm NATO","unlock":"Bullet Point assignment","desc":"The JNG-90 is a weapon introduced in the Battlefield 3: Close Quarters expansion and is unlocked upon the completion of the Bullet Point assignment. It was first seen in the Close Quarters Donya Fortress Gameplay Trailer."},{"name":"M417","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/c/c7/HK417.png/revision/latest","kit":"Recon","fire":"Semi-Automatic","rof":"295 RPM","magazine":"20 + 1 rounds","damage":"50 - 37.5","velocity":"450 m/s","ammo":"7.62x51mm NATO","unlock":"","desc":"The M417 is a weapon introduced in the Battlefield 3: Close Quarters expansion and is unlocked upon the completion of the Team Player assignment. It was first seen in the Close Quarters Donya Fortress Gameplay Trailer through the killfeed."},{"name":"M82A3","group":"Sniper Rifles","image":"https://static.wikia.nocookie.net/battlefield/images/4/4b/Barret_M82A3_Side_Render.png/revision/latest","kit":"","fire":"Semi-Automatic","rof":"125 RPM","magazine":"10 + 1 rounds","damage":"110","velocity":"","ammo":"","unlock":"","desc":"The M82A3 is a weapon featured in the singleplayer campaign of Battlefield 3. It has a 10-round magazine, semi-automatic fire mode, and extremely high firepower. It is only usable during the mission Kaffarov, where it is automatically equipped by Dimitri Mayakovsky after taking out a sniper in a fist-fight. Unlike the other weapons in the game, it has no name or pickup icon. The weapon comes equipped with an infrared scope."},{"name":"870MCS","group":"Shotguns","image":"https://static.wikia.nocookie.net/battlefield/images/0/05/870MCS.png/revision/latest","kit":"All","fire":"Pump-Action","rof":"125 RPM","magazine":"4 + 1 shells","damage":"Buckshot: 20 - 6 x 12 (240 - 72)","velocity":"350 m/s","ammo":"","unlock":"Rank 1","desc":"The 870MCS is a weapon featured in Battlefield 3."},{"name":"M1014","group":"Shotguns","image":"https://static.wikia.nocookie.net/battlefield/images/a/a9/M1014_Battlelog_Icon.png/revision/latest","kit":"Assault, Support, Engineer, Recon","fire":"Semi-automatic","rof":"220 RPM","magazine":"4 + 1 shells","damage":"Buckshot: 16 - 6 x 10 (160 - 60)","velocity":"Buckshot and Slugs: 300m/s","ammo":"","unlock":"Rank 22","desc":"The M1014 is an all kit shotgun featured in Battlefield 3."},{"name":"Saiga 12K","group":"Shotguns","image":"https://static.wikia.nocookie.net/battlefield/images/0/0f/Saiga_20K.png/revision/latest","kit":"All","fire":"Semi-Automatic","rof":"220 RPM","magazine":"6 + 1 shells","damage":"Buckshot: 18 - 6 x 9 (172 - 54)","velocity":"Buckshot and Slugs: 300 m/s","ammo":"","unlock":"Rank 34","desc":""},{"name":"DAO-12","group":"Shotguns","image":"https://static.wikia.nocookie.net/battlefield/images/4/41/BF3_DAO-12_ICON.png/revision/latest","kit":"All","fire":"Semi-Automatic","rof":"220 RPM","magazine":"8 shells","damage":"16 - 6 x8 (Buckshot) (128 - 48)","velocity":"","ammo":"","unlock":"Rank 38","desc":"The DAO-12 is a weapon featured in Battlefield 3. The shotgun fires in semi-automatic mode and has a rate of fire of 220 rounds per minute, or 180 rounds per minute if firing 12 Gauge Frag rounds; firing rapidly produces mild recoil. It has magazine size of eight rounds or twelve with Extended Magazine (regardless of any previous rounds inside)."},{"name":"USAS-12","group":"Shotguns","image":"https://static.wikia.nocookie.net/battlefield/images/6/6c/USAS-12.png/revision/latest","kit":"","fire":"Full Automatic, Semi-auto","rof":"300 RPM","magazine":"6 + 1 rounds","damage":"18-6 (x7) (126-42) With Buckshot","velocity":"","ammo":"","unlock":"Rank 43","desc":"The USAS-12 is a weapon featured in Battlefield 3. The shotgun fires in semi-automatic mode and fully auto and has a rate of fire of 300 rounds per minute and fires at a lower rounds per minute if firing 12 Gauge Frag rounds. Firing rapidly produces heavy recoil for a shotgun. It has magazine size of six rounds or ten with Extended Magazine, plus one in the chamber if reloaded with rounds left over."},{"name":"MK3A1","group":"Shotguns","image":"https://static.wikia.nocookie.net/battlefield/images/2/2e/BF3_MK3A1_ICON.png/revision/latest","kit":"All","fire":"Automatic","rof":"255 rounds per minute","magazine":"8 + 1 rounds","damage":"16-6 x8 with buckshot (128-48)","velocity":"","ammo":"","unlock":"Scarred Veteran assignment","desc":"The MK3A1 is a weapon introduced in the Battlefield 3: Back to Karkand expansion and is unlocked upon the completion of the Scarred Veteran assignment. It has more ammunition than the USAS-12 when equipped with extended magazines with 12+1 rounds available. It has high recoil if fired fully automatically while aimed down the sight, but only after the first 3-4 shots. The extended ammo specialization is highly recommended, as the MK3A1 uses ammo very quickly."},{"name":"SPAS-12","group":"Shotguns","image":"https://static.wikia.nocookie.net/battlefield/images/6/60/SPAS12.png/revision/latest","kit":"All","fire":"Pump-Action","rof":"150 RPM","magazine":"4 + 1 shells","damage":"Buckshot: 16 - 6 x 11 (176 - 66)","velocity":"300 m/s (Buckshot, Flechette and Slugs)","ammo":"Buckshot","unlock":"","desc":"The SPAS-12 is a pump action shotgun introduced in the Battlefield 3: Close Quarters expansion for Battlefield 3. It is unlocked upon the completion of the These Hurt Too assignment. Similar to the 870MCS in its operation (it is pump action) but it pumps slightly faster, and has slightly less pellet spread, in exchange for one less pellet per shot."},{"name":"PP-2000","group":"Personal Defense Weapons","image":"https://static.wikia.nocookie.net/battlefield/images/9/97/Pp2000_Battlelog.png/revision/latest","kit":"All","fire":"Automatic, Semi-Automatic","rof":"650 RPM","magazine":"20 + 1 rounds","damage":"25 - 13.7","velocity":"360 m/s","ammo":"9x19mm Parabellum","unlock":"Rank 7","desc":"The PP-2000 is a PDW featured in Battlefield 3."},{"name":"UMP-45","group":"Personal Defense Weapons","image":"https://static.wikia.nocookie.net/battlefield/images/d/df/Ump_Battlelog.png/revision/latest","kit":"All kits","fire":"Automatic, Two-round burst, Semi-automatic","rof":"600 RPM","magazine":"25 + 1 rounds","damage":"34 - 12.5","velocity":"320m/s","ammo":".45ACP","unlock":"Rank 16","desc":"The UMP45 is a weapon featured in Battlefield 3."},{"name":"PDW-R","group":"Personal Defense Weapons","image":"https://static.wikia.nocookie.net/battlefield/images/3/31/Magpul_Battlelog.png/revision/latest","kit":"All kits","fire":"Full-automatic, Three-rounds burst, Semi-automatic","rof":"750 RPM","magazine":"20 + 1 rounds","damage":"25 - 14.3","velocity":"430m/s","ammo":"5.56x45mm NATO","unlock":"Rank 32","desc":"The PDW-R was first seen in the four-page fact sheet from EA."},{"name":"P90","group":"Personal Defense Weapons","image":"https://static.wikia.nocookie.net/battlefield/images/c/c2/P90.png/revision/latest","kit":"All","fire":"Automatic, Semi-Automatic","rof":"900 RPM","magazine":"50 + 1 rounds","damage":"20 - 11.2","velocity":"420 m/s","ammo":"5.7x28mm","unlock":"Rank 40","desc":"The P90 is an all-kit weapon featured in Battlefield 3."},{"name":"MP7","group":"Personal Defense Weapons","image":"https://static.wikia.nocookie.net/battlefield/images/9/9b/Battlelog-mp7.png/revision/latest","kit":"all kits","fire":"Full-automatic, Semi-automatic","rof":"950 RPM","magazine":"20 + 1 rounds","damage":"20 - 11.2","velocity":"390m/s","ammo":"4.6x30mm","unlock":"34,000 Co-op score","desc":"The MP7 is featured in Battlefield 3 as a PDW."},{"name":"AS Val","group":"Personal Defense Weapons","image":"https://static.wikia.nocookie.net/battlefield/images/3/3b/Asval_Battlelog.png/revision/latest","kit":"All","fire":"Automatic, Semi-Automatic","rof":"900 RPM","magazine":"20 + 1 rounds","damage":"20 - 18.4","velocity":"333 m/s","ammo":"9x39mm","unlock":"Rank 45","desc":"The AS VAL is an integrally suppressed Soviet designed Assault Rifle developed for use in the Spetsnaz. Chambered for a special high performance armor piercing 9x39mm round, the AS VAL includes mounts for using optical, red dot or even night vision scopes. The VAL is designed to be fired only with the suppressor attached, and therefore prevents the rifle from mounting underslung attachments."},{"name":"PP-19","group":"Personal Defense Weapons","image":"https://static.wikia.nocookie.net/battlefield/images/7/79/BF3_PP-19_ICON.png/revision/latest","kit":"All","fire":"Automatic, Semi-Automatic","rof":"900 RPM","magazine":"54 + 1 rounds","damage":"16.7 - 12.5","velocity":"320 m/s","ammo":"9x18mm Makarov","unlock":"","desc":""},{"name":"M5K","group":"Personal Defense Weapons","image":"https://static.wikia.nocookie.net/battlefield/images/e/e7/M5K.png/revision/latest","kit":"All","fire":"Full-automatic, 2-round burst, Semi-automatic","rof":"900 RPM","magazine":"20 + 1 rounds","damage":"25 - 13.75","velocity":"380 m/s","ammo":"9x19mm","unlock":"Holt the Trigger assignment","desc":"The M5K is a weapon introduced in the Battlefield 3: Close Quarters expansion and is unlocked upon the completion of the Hold the Trigger assignment. It was first seen in the Close Quarters Gameplay Premiere trailer."},{"name":"M9","group":"Handguns","image":"https://static.wikia.nocookie.net/battlefield/images/5/58/M9.png/revision/latest","kit":"","fire":"Semi-Automatic","rof":"400 RPM","magazine":"15 + 1","damage":"25.0-13.75","velocity":"380 m/s","ammo":"9x19mm Parabellum","unlock":"Default for USMC","desc":"The M9 is a weapon featured in Battlefield 3."},{"name":"MP443","group":"Handguns","image":"https://static.wikia.nocookie.net/battlefield/images/a/a8/MP443.png/revision/latest","kit":"All","fire":"Semi-Automatic","rof":"460 RPM","magazine":"17 + 1 rounds","damage":"25 - 13.75","velocity":"320 m/s","ammo":"9×19mm Parabellum","unlock":"Default (Russian Army)","desc":"Designed to replace the dated PMM pistol, the MP443 Grach pistol was developed in 1993 and fires high powered armor-piercing 9mm Russian rounds. The pistol is a combined construction of polymers and steel and has been adopted by select Special Forces units in the Russian military."},{"name":"G17C","group":"Handguns","image":"https://static.wikia.nocookie.net/battlefield/images/c/cd/G17C.png/revision/latest","kit":"All Kits","fire":"","rof":"460 RPM","magazine":"17 + 1 rounds","damage":"25 - 13.75","velocity":"375 m/s","ammo":"9x19mm","unlock":"Rank 4","desc":"The G17C pistol is part of a large series of pistols from an Austrian manufacturer. Chambered in 9mm, this full sized combat pistol features a polymer frame and anti-corrosion surfaces that make it incredibly reliable. The G17C is incredibly popular with both Police and Military units worldwide. This G17C has been equipped with an integral Laser Sight that makes unaimed fire more accurate."},{"name":"M1911","group":"Handguns","image":"https://static.wikia.nocookie.net/battlefield/images/b/b2/M1911.png/revision/latest","kit":"All","fire":"Semi-Automatic","rof":"333 RPM","magazine":"8 + 1 rounds","damage":"34 - 12.5","velocity":"300 m/s","ammo":".45ACP","unlock":"","desc":"The M1911 is a weapon featured in Battlefield 3. Unlike previous iterations, it is only available to members of the EA Gun Club or Battlefield Veteran. For Battlefield 3 the M1911 has been redesigned after the Marine\u0027s Force Recon sidearm."},{"name":".44 Magnum","group":"Handguns","image":"https://static.wikia.nocookie.net/battlefield/images/7/78/Taurus44.png/revision/latest","kit":"All","fire":"Double-action","rof":"180 RPM","magazine":"6 rounds","damage":"60 - 30","velocity":"460 m/s","ammo":".44 Magnum","unlock":"Level 36 (.44 Magnum)","desc":"The .44 Magnum is a large-caliber revolver that is featured in Battlefield 3. It features high power, high accuracy, and recoil, with a lower rate of fire, and sharp and easy to use iron sights . It has a 6-round capacity and reloads with a speed-loader."},{"name":"MP412 REX","group":"Handguns","image":"https://static.wikia.nocookie.net/battlefield/images/c/c3/BF3_MP412_REX_ICON.png/revision/latest","kit":"All","fire":"Double-action","rof":"255 RPM","magazine":"6 rounds","damage":"50 - 20","velocity":"300 m/s","ammo":"","unlock":"5,000 Co-op XP","desc":"The MP412 REX is an all-kit weapon featured in Battlefield 3. It deals high damage and will kill enemies in 2-5 rounds, depending on distance. At close range, a headshot with the MP412 will always kill an enemy in 1 shot. It\u0027s worth noting it has a slightly worse hip fire accuracy than the other pistols except the automatics at 1.25."},{"name":"G18","group":"Handguns","image":"https://static.wikia.nocookie.net/battlefield/images/6/61/G18_Battlelog_Icon.png/revision/latest","kit":"All","fire":"Automatic, Semi-Automatic","rof":"900 RPM","magazine":"19 + 1","damage":"20 - 12.8","velocity":"375 m/s","ammo":"9x19mm Parabellum","unlock":"30","desc":"Essentially an Automatic version of the G17C, the G18 was developed for the Austrian EKO Cobra counter-terrorist force. Classified as a Machine Pistol, the G18 has been equipped with a number of modifications to allow greater control over its very rapid fire. Regardless, the G18 in Automatic is incredibly difficult to fire effectively at anything other than extremely short ranges."},{"name":"93R","group":"Handguns","image":"https://static.wikia.nocookie.net/battlefield/images/3/31/BF3BL93R.png/revision/latest","kit":"All","fire":"3-Round Burst, Semi-Automatic","rof":"900 RPM","magazine":"20 + 1 rounds","damage":"20 - 12.5 (60 - 37.5 per burst)","velocity":"380 m/s","ammo":"9x19mm Parabellum","unlock":"315,000 Co-op XP (before patch)","desc":"The 93R is a weapon featured in Battlefield 3. It is the fifth Co-op unlock, requiring an overall Co-Op score of 86,000 points to unlock."}],"maps":[{"name":"Caspian Border","group":"Battlefield 3","image":"https://static.wikia.nocookie.net/battlefield/images/d/db/Caspian-border-promo.jpg/revision/latest","modes":["Conquest","Rush","Squad Deathmatch","Squad Rush","Team Deathmatch"],"place":"Turkmen-Iranian Border","date":"2014","terrain":"Countryside, Woodland","desc":"Caspian Border is a map featured in Battlefield 3\u0027s multiplayer. Caspian Border is a multi-faceted, vehicle heavy map that exemplifies classic Battlefield gameplay. This map is fit for all classes as a result of a wide variety of vehicles and different terrains. It pits the United States Marine Corps against the Russian Army and set on the border between Iran and Turkmenistan near the Caspian Sea."},{"name":"Damavand Peak","group":"Battlefield 3","image":"https://static.wikia.nocookie.net/battlefield/images/a/a1/Damavandpeakloadingscreen.jpg/revision/latest","modes":["Conquest","Team Deathmatch","Squad Deathmatch","Rush"],"place":"Mount Damavand, Iran","date":"2014","terrain":"Mountainous","desc":"Damavand Peak (Persian: قله دماوند) is a map featured in Battlefield 3, taking place at Iran\u0027s highest peak, Mount Damavand. The map\u0027s distinguishing feature is a five hundred meter base jump between the 2nd and 3rd sets of M-COM stations in the Rush game mode."},{"name":"Kharg Island","group":"Battlefield 3","image":"https://static.wikia.nocookie.net/battlefield/images/0/02/Kharg_Island_Overview.png/revision/latest","modes":["All"],"place":"Kharg Island, The Persian Gulf","date":"2014","terrain":"Rocky, Urban","desc":"Kharg Island (Persian: جزیره خارگ‎) is a map featured in Battlefield 3 and is one of the nine maps in the standard edition. The map is inspired by the real-life Kharg Island (or Khark, depending on the romanization). At roughly eight square miles (approximately 20 square kilometers), the island contains an airfield, a paved circuit serving the northern region, and the KHEMCO oil facility in the south. A wildlife refuge is located on an island roughly two miles to the northeast. It is one of the largest maps of the base game."},{"name":"Noshahr Canals","group":"Battlefield 3","image":"https://static.wikia.nocookie.net/battlefield/images/9/9f/BF3_Noshahr_Canals_Screen.png/revision/latest","modes":["Conquest","Rush","Squad Deathmatch","Squad Rush","Team Deathmatch"],"place":", Iran","date":"2014","terrain":"Urban, Docks, Rocky","desc":"Noshahr Canals is one of the nine multiplayer maps available in the standard edition of Battlefield 3. The map is set in the Port of Noshahr in Iran. This map contrasts the urban and rural areas with a more industrial setting. The Noshahr Canals were set up to serve as an industrial harbor, featuring a mix of infantry, land vehicle, and boat gameplay and was the only original map to feature mobile anti-aircraft on consoles."},{"name":"Operation Firestorm","group":"Battlefield 3","image":"https://static.wikia.nocookie.net/battlefield/images/1/19/Bf3-operation-firestorm-2.jpg/revision/latest","modes":["Conquest","Rush","Team Deathmatch","Squad Deathmatch","Squad Rush"],"place":", Iran","date":"2014","terrain":"Desert","desc":"Operation Firestorm (Persian: عملیات طوفان آتش) is a map featured in Battlefield 3\u0027s multiplayer. The map is set in , in Iran, with the United States Marine Corps engaging the Russian Army. The map is large scale with a variety of vehicles, similar to Caspian Border. This map is generally varied with tight, close, indoor fights inside the warehouses ideal for personal defense weapons and shotguns, medium range fights between each flag where vehicles are often found, and extremely long sight lines with many elevated positions making it ideal for sniping and SOFLAM usage."},{"name":"Operation Métro","group":"Battlefield 3","image":"https://static.wikia.nocookie.net/battlefield/images/8/8e/Metroloadscreen.jpg/revision/latest","modes":["All"],"place":"Paris, France","date":"2014","terrain":"Urban, Underground","desc":"Operation Métro is set in Paris, France, similar to Seine Crossing, but takes place in a park, the underground metro system, and a cafe surrounded by apartment buildings and the Paris Stock Exchange."},{"name":"Seine Crossing","group":"Battlefield 3","image":"https://static.wikia.nocookie.net/battlefield/images/9/97/BF3_Seine_Crossing_Screen.png/revision/latest","modes":["All"],"place":"Pont Saint-Michel","date":"2014","terrain":"Urban","desc":"Seine Crossing (French: Traversée de la Seine) is a map featured in Battlefield 3. It is set in downtown Paris, similar to Operation Métro, and features the Seine River, which runs through the city. The map\u0027s large number of roads allow for vehicle warfare, while tight alleys and staircases allow for easy access to the many buildings with second or third levels to provide a better tactical position. Firefights often occur at close range, between or in buildings and across streets."},{"name":"Tehran Highway","group":"Battlefield 3","image":"https://static.wikia.nocookie.net/battlefield/images/d/db/TEHRANHIGHWAY_SC2.jpg/revision/latest","modes":["All"],"place":"Tehran, Iran","date":"2014","terrain":"Urban","desc":"Tehran Highway (Persian: بزرگراه تهران) is one of the nine multiplayer maps in Battlefield 3. As the name suggests, it is set in a highway in the Iranian Capital of Tehran, however since the highways of Tehran are around 180 km in length, it is probably one of the more famous highways such as the Modarres or the Hemmat. Tehran Highway is perfect for snipers due to its elevated terrain, multiple hide-outs and its dark setting. As a mid-sized map, MAVs have increased flight ceiling, lower than the mid-sized air maps, but enough to keep them away from fire. Players spawning on Radio Beacons are not airdropped."},{"name":"Wake Island","group":"Back to Karkand","image":"https://static.wikia.nocookie.net/battlefield/images/f/fd/WAKE_ISLAND_2014_BTK_OVERVIEW.png/revision/latest","modes":["All"],"place":"Wake Island, Pacific Ocean","date":"2014","terrain":"Beach, Island","desc":"Wake Island is a map available in the Battlefield 3: Back to Karkand expansion pack. It is much darker and war-torn than the previous version of the map, as well as having a much larger and open area."},{"name":"Donya Fortress","group":"Close Quarters","image":"https://static.wikia.nocookie.net/battlefield/images/3/38/Donya_Overview.jpg/revision/latest","modes":["Conquest Domination, Team Deathmatch, Squad Deathmatch, Gun Master"],"place":"Tehran, Iran","date":"2014","terrain":"Indoors, Narrow Hallways, Multilevel","desc":"Donya Fortress (Persian: دژ دنیا) is one of the four maps featured in the Battlefield 3: Close Quarters expansion pack."},{"name":"Operation 925","group":"Close Quarters","image":"https://static.wikia.nocookie.net/battlefield/images/e/ef/Operation_925.jpg/revision/latest","modes":["Conquest Domination, Gun Master, Team Deathmatch, Squad Deathmatch"],"place":"Tehran, Iran","date":"2014","terrain":"Indoors, Urban, Multilevel","desc":"Operation 925 (Persian: عملیات ۹۲۵) is a map included in the Battlefield 3: Close Quarters expansion pack, and is located in a commercial building in Tehran."},{"name":"Scrapmetal","group":"Close Quarters","image":"https://static.wikia.nocookie.net/battlefield/images/a/a3/Scrapmetal.jpg/revision/latest","modes":["Conquest Domination, Gun Master, Team Deathmatch, Squad Deathmatch"],"place":"Near Tehran, Iran","date":"2014","terrain":"Indoors, Narrow Hallways, Multilevel","desc":"Scrapmetal is a map featured in the Battlefield 3: Close Quarters expansion. Set inside and on the rooftops of an abandoned factory near Tehran, Iran, the map features multiple stories and skybridges that separate the flags. It is only playable in the game modes Conquest Domination, Gun Master, Squad Deathmatch, and Team Deathmatch Close Quarters."},{"name":"Ziba Tower","group":"Close Quarters","image":"https://static.wikia.nocookie.net/battlefield/images/6/6a/BF3CQ_Ziba_Tower.png/revision/latest","modes":["Conquest Domination, Gun Master, Team Deathmatch, Squad Deathmatch"],"place":"Tehran, Iran","date":"2014","terrain":"Indoors, Narrow Hallways, Multilevel","desc":"Ziba Tower (Persian: برج زیبا) is a featured in the Battlefield 3: Close Quarters expansion. The map is located in the middle of Tehran, Iran."},{"name":"Alborz Mountains","group":"Armored Kill","image":"https://static.wikia.nocookie.net/battlefield/images/b/b5/Alborz_Mountain.png/revision/latest","modes":["All base game modes, Tank Superiority"],"place":"Alborz Mountains, Iran","date":"2014","terrain":"Mountainous, Woodland","desc":"Alborz Mountains (Persian: کوه‌های‌ البرز) is a map featured in the Battlefield 3: Armored Kill expansion. The map is set within the snow-covered Alborz mountain range, located in northern Iran."},{"name":"Armored Shield","group":"Armored Kill","image":"https://static.wikia.nocookie.net/battlefield/images/7/7f/Battlefield-3-Armored-Kill-Armored-Shield-map.jpg/revision/latest","modes":["All base game modes, Tank Superiority"],"place":"Sanoy, Chechnya, Russia","date":"2014","terrain":"Countryside, Woodland","desc":"Armored Shield is a map featured in the Battlefield 3: Armored Kill expansion. It is set in the outskirts of the fictional city of Sanoy, Russia."},{"name":"Bandar Desert","group":"Armored Kill","image":"https://static.wikia.nocookie.net/battlefield/images/0/0a/Bandar_Desert.jpg/revision/latest","modes":["All base game modes, Tank Superiority"],"place":"Bandar-e-Abbas, Iran","date":"2014","terrain":"Desert","desc":"Bandar Desert (Persian: صحرا بندر) is a map featured in the Battlefield 3: Armored Kill expansion. Bandar Desert is located near Bandar Abbas, a seaport in southern Iran, as it is surrounded by a desert. It is the second largest map in Battlefield history, behind Halvøy."},{"name":"Death Valley","group":"Armored Kill","image":"https://static.wikia.nocookie.net/battlefield/images/e/e4/AK_Death_Valley.png/revision/latest","modes":["All base game modes, Tank Superiority"],"place":"Turkmen-Iranian Border","date":"2014","terrain":"Rocky, Forest","desc":"Death Valley (Persian: دره مرگ) is a map featured in the Battlefield 3: Armored Kill expansion. The setting of the map is at night in a valley near the Turkmenistan-Iran border, with several dead trees dotting the map. It also features a large under-construction office building, identical to the one in Gulf of Oman."},{"name":"Azadi Palace","group":"Aftermath","image":"https://static.wikia.nocookie.net/battlefield/images/a/a1/Azadi_Palace2.jpg/revision/latest","modes":["Conquest","Scavenger","Rush","Squad Rush","Team Deathmatch","Squad Deathmatch","Gun Master"],"place":"Tehran, Iran","date":"2014","terrain":"Urban Aftermath","desc":"Azadi Palace (Persian: کاخ آزادی) is a map featured in the Battlefield 3: Aftermath expansion. The map takes place within and around an Iranian parliament building in Tehran, with a maze-like gameplay focus."},{"name":"Epicenter","group":"Aftermath","image":"https://static.wikia.nocookie.net/battlefield/images/e/e9/Epicenter_Picture_Prima_Guide.png/revision/latest","modes":["Conquest","Scavenger","Rush","Squad Rush","Team Deathmatch","Squad Deathmatch"],"place":"Tehran, Iran","date":"2014","terrain":"Urban Aftermath","desc":"Epicenter (Persian: رومرکز) is a map featured in the Battlefield 3: Aftermath expansion. The map takes place within a post-earthquake Tehran."},{"name":"Markaz Monolith","group":"Aftermath","image":"https://static.wikia.nocookie.net/battlefield/images/1/12/Markaz_Monolith_Prima_Guide.png/revision/latest","modes":["Conquest","Scavenger","Rush","Squad Rush","Team Deathmatch","Squad Deathmatch","Gun Master"],"place":"Tehran, Iran","date":"2014","terrain":"Urban Aftermath","desc":"Markaz Monolith (Persian: یکپارچه مرکز) is a map featured in the Battlefield 3: Aftermath expansion. This map is set just after the events of the third campaign mission, Uprising, and the location is set in Iran."},{"name":"Talah Market","group":"Aftermath","image":"https://static.wikia.nocookie.net/battlefield/images/4/47/Talah_Market.jpg/revision/latest","modes":["Conquest Assault","Scavenger","Rush","Squad Rush","Team Deathmatch","Squad Deathmatch","Gun Master"],"place":"Yazd, Iran","date":"2014","terrain":"Urban Aftermath","desc":"Talah Market (Persian: بازار طلا) is a map featured in the Battlefield 3: Aftermath expansion. The map is set within the city of Yazd, located in central Iran. The layout of the map primarily focusing on vertical and symmetrical gameplay."},{"name":"Kiasar Railroad","group":"End Game","image":"https://static.wikia.nocookie.net/battlefield/images/0/0c/End_Game_Kiasar_Railroad_Water.jpg/revision/latest","modes":["All base modes, Capture the Flag, Air Superiority"],"place":"Kiasar, Iran","date":"2014","terrain":"Forest, Rocky","desc":"Kiasar Railroad (Persian: راه آهن كياسر‎) is a map featured in the Battlefield 3: End Game expansion. It is set near the small city of Kiasar, in northern Iran. Each of the four new maps in End Game are season-themed, with Kiasar Railroad taking place in the spring."},{"name":"Nebandan Flats","group":"End Game","image":"https://static.wikia.nocookie.net/battlefield/images/4/4a/End_Game_Nebandan_Flats_Thumb.jpg/revision/latest","modes":["All Base Modes, Capture the Flag, Air Superiority"],"place":"Nehbandan, Iran","date":"2014","terrain":"Desert, Flat","desc":"Nebandan Flats (Persian: کویر نهبندان) is a map featured in the Battlefield 3: End Game expansion. It is set near Nehbandan, in eastern Iran. Each of the four new maps in End Game are season-themed, with Nebandan Flats taking place in the summer."},{"name":"Operation Riverside","group":"End Game","image":"https://static.wikia.nocookie.net/battlefield/images/7/76/End_Game_Operation_Riverside_Water.jpg/revision/latest","modes":["All base modes, Capture the Flag, Air Superiority"],"place":"Northern Iran","date":"2014","terrain":"Countryside, Woodland","desc":"Operation Riverside (Persian: عملیات کنار رودخانه) is a map featured in the Battlefield 3: End Game expansion. Each of the four new maps in End Game are season-themed, with Operation Riverside taking place in autumn, in northern Iran."},{"name":"Sabalan Pipeline","group":"End Game","image":"https://static.wikia.nocookie.net/battlefield/images/d/d5/End_Game_Sabalan_Pipeline_Water.jpg/revision/latest","modes":["All base modes, Capture the Flag, Air Superiority"],"place":"Mount Sabalan, Iran","date":"2014","terrain":"Snow, Wooded, Rocky","desc":"Sabalan Pipeline (Persian: خط لوله سبلان) is a map featured in the Battlefield 3: End Game expansion. Each of the four new maps in End Game are season-themed, with Sabalan Pipeline taking place at an oil refinery near Sabalan, a mountain in northwestern Iran, during winter with snow-covered terrain."},{"name":"Omaha Desert","group":"Cut","image":null,"modes":["Rush"],"place":"","date":"2014","terrain":"Desert","desc":"Omaha Desert is an unreleased map that was meant to be featured in Battlefield 3. The map would have featured tanks coming from the desert to a ridge base, similar to Omaha Beach. The name was only a working title and would have been changed before release. It was ultimately cut due to being too generic compared to other maps in development at the time."}]};
